from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
from pathlib import Path
rw=Chem.RWMol(); names={}
def atom(name,el,ar=False):
 a=Chem.Atom(el); a.SetIsAromatic(ar); i=rw.AddAtom(a);names[name]=i;return i
def bond(a,b,order=Chem.BondType.SINGLE):
 rw.AddBond(names[a] if isinstance(a,str) else a,names[b] if isinstance(b,str) else b,order)
for name,el in [('c0','C'),('c1','C'),('c2','C'),('c3','C'),('c4','C'),('nL','N'),('c6','C'),('c7','C'),('c8','C'),('nR','N')]:atom(name,el,True)
for a,b in [('c0','c1'),('c1','c2'),('c2','c3'),('c3','c4'),('c4','nL'),('nL','c0'),('c1','c6'),('c6','c7'),('c7','c8'),('c8','nR'),('nR','c0')]:bond(a,b,Chem.BondType.AROMATIC)
for side,c in [('L','c4'),('R','c8')]:
 for name,el in [('ch','C'),('p','P'),('imc','C'),('imn','N'),('me','C')]:atom(name+side,el)
 for a,b,o in [(c,'ch',1),('ch','p',1),('ch','imc',1),('imc','imn',2),('imc','me',1)]:
  bond(a if a==c else a+side,b+side,Chem.BondType.DOUBLE if o==2 else Chem.BondType.SINGLE)
 for k in range(2):
  nm=f'tb{side}{k}';atom(nm,'C');bond('p'+side,nm)
  for j in range(3):atom(nm+str(j),'C');bond(nm,nm+str(j))
for side in ['L','R']:
 for nm,el in [('acnN','N'),('acnC','C'),('acnMe','C')]:atom(nm+side,el)
 bond('acnN'+side,'acnC'+side,Chem.BondType.TRIPLE);bond('acnC'+side,'acnMe'+side)
m=rw.GetMol();Chem.SanitizeMol(m);m=Chem.AddHs(m)
print(Chem.MolToSmiles(Chem.RemoveHs(m)),m.GetNumAtoms(),names,flush=True)
params=AllChem.MMFFGetMoleculeProperties(m)
print('MMFF params',params is not None,flush=True)
# Core positions. View z>0 toward viewer; both chlorides bracket the metal-metal line.
core={'c0':(0,0,0),'c1':(0,1.40,0),'c2':(-1.212,2.10,0),'c3':(-2.425,1.40,0),'c4':(-2.425,0,0),'nL':(-1.212,-.70,0),'c6':(1.212,2.10,0),'c7':(2.425,1.40,0),'c8':(2.425,0,0),'nR':(1.212,-.70,0)}
RuL=np.array([-1.70,-2.72,0.0]); RuR=np.array([1.70,-2.72,0.0]); ClB=np.array([0,-2.85,-1.72]);ClF=np.array([0,-2.85,1.72])
left={'ch':(-3.64,-.88,0),'p':(-3.63,-2.27,-1.20),'imc':(-4.04,-1.34,1.37),'imn':(-3.40,-2.42,1.38),'me':(-5.12,-.76,2.15),'acnN':(-1.91,-4.78,-.03),'acnC':(-2.03,-5.93,-.05),'acnMe':(-2.18,-7.38,-.07)}
for nm,p in left.items():
 core[nm+'L']=p;core[nm+'R']=(-p[0],p[1],-p[2])
# initialize and fit all organic atoms to core template; tBu and H find free coordinates
best=None
for seed in range(5):
 ps=AllChem.ETKDGv3();ps.randomSeed=842+seed;ps.useRandomCoords=True
 res=AllChem.EmbedMolecule(m,ps)
 if res<0:continue
 for k in [3,20,100,300]:
  ff=AllChem.MMFFGetMoleculeForceField(m,params,ignoreInterfragInteractions=False)
  for nm,pt in core.items():
   idx=ff.AddExtraPoint(*pt,fixed=True)-1
   ff.MMFFAddDistanceConstraint(names[nm],idx,False,0,0,k)
  ff.Initialize();ff.Minimize(maxIts=3000)
 # core is constrained less tightly in final fitting, actual bonding lengths improve
 energy=ff.CalcEnergy()
 pos=np.array(m.GetConformer().GetPositions())
 rms=np.sqrt(np.mean([np.sum((pos[names[n]]-p)**2) for n,p in core.items()]))
 print(seed,energy,'rms',rms,flush=True)
 if best is None or energy<best[0]:best=(energy,pos)
conf=m.GetConformer()
for i,pt in enumerate(best[1]):conf.SetAtomPosition(i,pt)
Chem.MolToMolFile(m,'organic.mol')
np.savez('build_data.npz',pos=best[1],names=names,core=core)
# All-atom final complex includes bridging chlorides and two RuII.
with open('initial.xyz','w') as f:
 f.write(f'{m.GetNumAtoms()+4}\nDicationic dinuclear ruthenium complex; all H explicit; charge +2\n')
 for a,pt in zip(m.GetAtoms(),best[1]):f.write(f'{a.GetSymbol():2s} {pt[0]: .9f} {pt[1]: .9f} {pt[2]: .9f}\n')
 for el,pt in [('Ru',RuL),('Ru',RuR),('Cl',ClB),('Cl',ClF)]:f.write(f'{el:2s} {pt[0]: .9f} {pt[1]: .9f} {pt[2]: .9f}\n')
